{
  "message": "I found the following promotional options. Offer availability depends on the promotion window and approval at the time you apply:",
  "options": [
    {
      "card": "EcoCard",
      "best_for": "Largest documented sign-up bonus",
      "offer": "Earn 2,000 sustainability points—worth $20 as a statement or checking-account credit—after spending $5,000 in eligible purchases during the first month.",
      "offer_window": "August 1, 2025 through December 15, 2025",
      "key_terms": "No minimum credit score requirement; $50 annual fee; 19.99% APR on carried balances; returns, fees, balance transfers, cash equivalents, and disputed transactions do not count toward the spending requirement."
    },
    {
      "card": "Silver Zoom Card",
      "best_for": "Enhanced cash back over time",
      "offer": "Triple cash back for 9 months from account opening, after claiming the offer in your account portal.",
      "claim_window": "Through December 31, 2025",
      "key_terms": "The account must be open and in good standing, and the offer must be claimed and activated within the window."
    },
    {
      "card": "Business Silver Rewards Card",
      "best_for": "Business applicants seeking boosted cash back",
      "offer": "2x cash back on purchases for the first 6 months after opening. Travel and software purchases normally earn 10% and other purchases normally earn 1%, subject to exclusions.",
      "offer_window": "November 14, 2024 through November 14, 2025",
      "key_terms": "The account must be opened during the promotional period; no separate enrollment is required."
    },
    {
      "card": "Bronze Rewards Card",
      "best_for": "Introductory financing rather than rewards",
      "offer": "0% APR on carried balances for the first 12 months.",
      "offer_window": "September 1, 2025 through February 28, 2026",
      "key_terms": "After the introductory period, the APR becomes 20.49%. This is not a points or cash-back sign-up bonus."
    }
  ],
  "recommendation": "Based strictly on the documented sign-up bonus amount, the EcoCard is the strongest option: 2,000 points with a $5,000 first-month spending requirement. If you prefer ongoing cash back instead of a one-time bonus, the Silver Zoom promotion may be more attractive, provided it is still available and can be claimed.",
  "rewards_note": "Cash-back rewards are generally redeemable at 1 point = $0.01 for a statement credit or Rho-Bank checking-account credit. EcoCard sustainability points also redeem at $0.01 per point through those methods. Please verify the offer is displayed during the application process because promotional windows and terms may change."
}
